            win_moves = []
            for c in playable:
                rem = stones - c
                opp_play = [d for d in self.opp_cards if d <= rem]
                if not opp_play:
                    win_moves.append(c)
            if win_moves:
                chosen = min(win_moves)
            else:
                # 3) avoid moves that let opponent win immediately
                safe = []
                for c in playable:
                    rem = stones - c
                    # if opponent has a card equal to rem, they can win next
                    if rem in self.opp_cards:
                        continue
                    safe.append(c)
                if safe:
                    chosen = min(safe)
                else:
                    # 4) no safe moves: play smallest
                    chosen = min(playable)
        # return the chosen card
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen, type='custom')]
        )
